import{at as e,it as t,t as n,yt as r}from"./chunks/framework.Br18A9IS.js";var i=JSON.parse(`{"title":"Fix at the Source","description":"","frontmatter":{},"headers":[],"relativePath":"skills/contributors/fix-at-the-source.md","filePath":"skills/contributors/fix-at-the-source.md"}`),a={name:`skills/contributors/fix-at-the-source.md`};function o(n,i,a,o,s,c){return r(),t(`div`,null,[...i[0]||=[e(`<h1 id="fix-at-the-source" tabindex="-1">Fix at the Source <a class="header-anchor" href="#fix-at-the-source" aria-label="Permalink to “Fix at the Source”">​</a></h1><p>Use this skill whenever you&#39;re fixing a bug, adding a guard, or adding a fallback inside WarpDrive&#39;s internals (<code>Store</code>, cache, graph, reactive signals, record arrays). The question is never just &quot;where do I stop the crash&quot; — it&#39;s &quot;where does &#39;x changed&#39; fail to correctly produce &#39;y updated&#39;, and what&#39;s the one place that should know it.&quot;</p><h2 id="steps" tabindex="-1">Steps <a class="header-anchor" href="#steps" aria-label="Permalink to “Steps”">​</a></h2><ol><li>Trace the bug back to its root cause: the place where a change to one piece of state should have correctly propagated to another, and didn&#39;t. Fix there, not at the symptom&#39;s surface. A patch at the surface only treats the one call site that happened to crash or misbehave — every other consumer of the same broken invariant is still wrong.</li><li>That root cause is usually also the cheapest place to check: the earliest point in the call chain where the fact you need — &quot;is there new data to sync,&quot; &quot;did anything actually change&quot; — is already known or a single cheap check away (an <code>undefined</code> check, a reference comparison, a boolean already on the object). Put the fix there, immediately in front of the work it&#39;s guarding.</li><li>Centralize the check at that one source instead of duplicating a defensive check at every downstream consumer. Don&#39;t guard further upstream &quot;just in case&quot; (runs even when the expensive work wouldn&#39;t have happened) or further downstream after the fact (too late, and easy to miss a sibling call site that needs the same guard). One correct check at the source beats the same defensive check copy-pasted in ten places.</li><li>Don&#39;t reach for a wider fix (a new state field, a broader notification path, a refactor of how staleness is tracked) when a narrow, local check at the source does the job. Save the bigger change for when the narrow check turns out to be wrong somewhere else too.</li><li>Treat a fallback (<code>?? []</code>, <code>|| defaultValue</code>) that only exists to stop a crash as a smell, not a fix — it silently produces a plausible-looking wrong result instead of a loud one, and doesn&#39;t restore the &quot;x changed → y updated&quot; correctness that was actually broken. Prefer a guard that skips unnecessary work over a fallback that fabricates an input for it.</li><li>If the fix changes behavior that is documented — a TSDoc comment, a guide, or an upgrade page now says something untrue — update that documentation in the same PR. Follow <a href="./write-documentation">Write Documentation</a>; its checklist has a bug-fix row for exactly this case, and a fix that leaves the docs describing the old behavior isn&#39;t finished.</li></ol><h2 id="example" tabindex="-1">Example <a class="header-anchor" href="#example" aria-label="Permalink to “Example”">​</a></h2><p><code>ManyArrayManager#_syncArray</code> re-syncs a <code>ManyArray</code>&#39;s membership whenever its relationship goes stale. A relationship can go stale from a <code>links</code>-only update with no new <code>data</code> (e.g. a save response that only changes a pagination link) — in that case there is no membership to sync at all. The root cause was that staleness alone doesn&#39;t imply new membership data exists; the fix was a single <code>rawValue.data !== undefined</code> check placed directly in front of the clear-and-refill, the one place that has the fact it needs. Not a <code>?? []</code> fallback (which would silently empty an already-populated array on an unrelated links-only change, papering over the symptom instead of the cause) and not a fix upstream in the graph layer (which would touch every consumer of relationship state to fix a bug specific to this one array-sync path, trading a narrow correct check for a wide speculative one).</p>`,6)]])}var s=n(a,[[`render`,o]]);export{i as __pageData,s as default};